async function pdfInfo(data, signal) {
  if (new TextDecoder().decode(data.subarray(0, 5)) !== "%PDF-")
    throw new Error("format");
  await Promise.resolve().then(() => init_pdf());
  await Promise.resolve().then(() => init_pdf_worker());
  Object.assign(globalThis, { pdfjsWorker: { WorkerMessageHandler } });
  if (signal.aborted)
    throw new Error("cancelled");
  const task = getDocument({ data, useSystemFonts: false, disableFontFace: true, stopAtErrors: true });
  let encrypted = false;
  task.onPassword = () => {
    encrypted = true;
    task.destroy();
  };
  const abort = () => {
    task.destroy();
  };
  signal.addEventListener("abort", abort, { once: true });
  try {
    const doc = await task.promise;
    return { pages: doc.numPages };
  } catch (error) {
    if (encrypted)
      throw new Error("encrypted");
    if (error instanceof Error && error.name === "InvalidPDFException")
      throw new Error("format");
    throw error;
  } finally {
    signal.removeEventListener("abort", abort);
    await task.destroy();
  }
}

